  /* One cover ficha. Short lab = text molded on the lid (user photo). Full name is pin.note. Numbers and amps follow PG-26. */
  ipdm_cover:{group:'motor', sub:'ipdm', name:'Tapa IPDM · fusibles', meta:'PG-26 · 71–89', accent:'#ffca28', shape:'ipdm_cover', view:{unv:{es:'la grilla es la tapa impresa, con los números de PG-26; no hay cara T.S. de arnés.',en:'the grid is the printed cover, numbered from PG-26; there is no harness-plug face.',ja:'印刷カバーの格子。番号はPG-26。ハーネス側の面はない。'}}, note:'En esta tapa van los fusibles 71 a 89. Cada recuadro muestra el nombre corto que trae impreso la tapa, y al elegir un fusible aparece su nombre completo.',
    pins:[
      {id:'71',lab:'TAIL',code:'10A',ecm:null,note:'En la tapa dice TAIL LAMP (10A). Alimenta las luces de cola.',note_en:'The lid says TAIL LAMP (10A). It feeds the tail lamps.',note_ja:'カバーの表示はTAIL LAMP（10A）。テールランプに給電する。'},
      {id:'72',lab:'HI-RH',code:'10A',ecm:null,note:'En la tapa dice H/L HI-RH (10A). Es la luz alta del faro derecho.',note_en:'The lid says H/L HI-RH (10A). It is the right headlamp high beam.',note_ja:'カバーの表示はH/L HI-RH（10A）。右ヘッドランプのハイビーム用。'},
      {id:'73',lab:'WIP',code:'20A',ecm:null,note:'En la tapa dice FR WIP (20A). Alimenta el limpiaparabrisas.',note_en:'The lid says FR WIP (20A). It feeds the front wiper.',note_ja:'カバーの表示はFR WIP（20A）。フロントワイパーに給電する。'},
      {id:'74',lab:'HI-LH',code:'10A',ecm:null,note:'En la tapa dice H/L HI-LH (10A). Es la luz alta del faro izquierdo.',note_en:'The lid says H/L HI-LH (10A). It is the left headlamp high beam.',note_ja:'カバーの表示はH/L HI-LH（10A）。左ヘッドランプのハイビーム用。'},
      {id:'75',lab:'DEF',code:'20A',ecm:null,note:'En la tapa dice RR DEF (20A). Alimenta el desempañador de la luneta; sale por E4·6.',note_en:'The lid says RR DEF (20A). It feeds the rear-window defogger and leaves through E4·6.',note_ja:'カバーの表示はRR DEF（20A）。リヤデフォッガに給電し、E4·6から出る。'},
      {id:'76',lab:'LO-RH',code:'15A',ecm:null,note:'En la tapa dice H/L LO-RH (15A). Es la luz baja del faro derecho.',note_en:'The lid says H/L LO-RH (15A). It is the right headlamp low beam.',note_ja:'カバーの表示はH/L LO-RH（15A）。右ヘッドランプのロービーム用。'},
      {id:'77',lab:'IGN',code:'15A',ecm:null,note:'En la tapa dice IGN & ECCS CONT (15A). Es el relé del ECM: sale por E7·18 (cable R/W) hacia los pines 119 y 120 del ECM.',note_en:'The lid says IGN & ECCS CONT (15A). It is the ECM relay: it leaves through E7·18 (R/W wire) to ECM pins 119 and 120.',note_ja:'カバーの表示はIGN & ECCS CONT（15A）。ECMリレー用で、E7·18（R/W線）からECMの119番と120番へ行く。'},
      {id:'78',lab:'DEICE',code:'15A',ecm:null,note:'En la tapa dice WIPER DEICER (15A). Alimenta el deshielo del limpiaparabrisas.',note_en:'The lid says WIPER DEICER (15A). It feeds the wiper deicer.',note_ja:'カバーの表示はWIPER DEICER（15A）。ワイパーデアイサーに給電する。'},
      {id:'79',lab:'A/C',code:'10A',ecm:null,note:'En la tapa dice AIR CON (10A). Alimenta el aire acondicionado.',note_en:'The lid says AIR CON (10A). It feeds the air conditioner.',note_ja:'カバーの表示はAIR CON（10A）。エアコンに給電する。'},
      {id:'80',lab:'DEF',code:'20A',ecm:null,note:'En la tapa dice RR DEF (20A). Alimenta el desempañador de la luneta; sale por E4·5.',note_en:'The lid says RR DEF (20A). It feeds the rear-window defogger and leaves through E4·5.',note_ja:'カバーの表示はRR DEF（20A）。リヤデフォッガに給電し、E4·5から出る。'},
      {id:'81',lab:'FUEL',code:'15A',ecm:null,note:'En la tapa dice FUEL PUMP (15A). Es la salida del relé de la bomba de combustible: E8·39 (cable B/Y) va al pin 1 de la bomba.',note_en:'The lid says FUEL PUMP (15A). It is the fuel-pump relay output: E8·39 (B/Y wire) goes to pump pin 1.',note_ja:'カバーの表示はFUEL PUMP（15A）。燃料ポンプリレーの出力で、E8·39（B/Y線）がポンプの1番ピンへ行く。'},
      {id:'82',lab:'ABS',code:'10A',ecm:null,note:'En la tapa dice ABS CONT (10A). Alimenta el control del ABS.',note_en:'The lid says ABS CONT (10A). It feeds the ABS control.',note_ja:'カバーの表示はABS CONT（10A）。ABS制御に給電する。'},
      {id:'83',lab:'A/T',code:'10A',ecm:null,note:'En la tapa dice AT CONT (10A). En este arnés, E7·26 (cable G/W) alimenta las luces de marcha atrás (interruptor F36, LT-183), y ese pin está numerado como fusible 83.',note_en:'The lid says AT CONT (10A). On this harness E7·26 (G/W wire) feeds the back-up lamps (switch F36, LT-183), and that pin is numbered as fuse 83.',note_ja:'カバーの表示はAT CONT（10A）。このハーネスではE7·26（G/W線）がバックランプ（スイッチF36、LT-183）に給電していて、そのピンはヒューズ83の番号になっている。'},
      {id:'84',lab:'WASH',code:'10A',ecm:null,note:'En la tapa dice WASH MTR (10A). Alimenta el lavaparabrisas delantero y, en el Coupé, el lavaluneta.',note_en:'The lid says WASH MTR (10A). It feeds the front washer and, on the Coupe, the rear washer.',note_ja:'カバーの表示はWASH MTR（10A）。フロントウォッシャーと、クーペはリヤウォッシャーに給電する。'},
      {id:'85',lab:'O2',code:'15A',ecm:null,note:'En la tapa dice O2 SENS (15A). Alimenta los sensores de oxígeno.',note_en:'The lid says O2 SENS (15A). It feeds the oxygen sensors.',note_ja:'カバーの表示はO2 SENS（15A）。O2センサーに給電する。'},
      {id:'86',lab:'LO-LH',code:'15A',ecm:null,note:'En la tapa dice H/L LO-LH (15A). Es la luz baja del faro izquierdo.',note_en:'The lid says H/L LO-LH (15A). It is the left headlamp low beam.',note_ja:'カバーの表示はH/L LO-LH（15A）。左ヘッドランプのロービーム用。'},
      {id:'87',lab:'THR',code:'15A',ecm:null,note:'En la tapa dice THROTTLE MTR (15A). Es el relé del motor de la mariposa; el ECM lo vigila por E9·47.',note_en:'The lid says THROTTLE MTR (15A). It is the throttle-motor relay; the ECM watches it at E9·47.',note_ja:'カバーの表示はTHROTTLE MTR（15A）。スロットルモーターリレー用で、ECMがE9·47で監視している。'},
      {id:'88',lab:'FOG',code:'15A',ecm:null,note:'En la tapa dice FR FOG (15A). PG-26 marca el 88 con una X: ese lugar no lleva fusible.',note_en:'The lid says FR FOG (15A). PG-26 marks 88 with an X: there is no fuse in that slot.',note_ja:'カバーの表示はFR FOG（15A）。PG-26では88にXの印があり、ここにはヒューズが入らない。'},
      {id:'89',lab:'SOL',code:'10A',ecm:null,note:'En la tapa dice ENG SOL (10A). Según SC-13, el fusible 89 alimenta el interlock del embrague de los M/T por E7·25 (cable G/Y).',note_en:'The lid says ENG SOL (10A). Per SC-13, fuse 89 feeds the M/T clutch interlock through E7·25 (G/Y wire).',note_ja:'カバーの表示はENG SOL（10A）。SC-13によると、ヒューズ89はE7·25（G/Y線）からM/Tのクラッチインターロックに給電する。'}
    ]},
